WITH with_latest AS (SELECT s.id, s.customer_id, s.store_id, s.order_date, s.status, latest.payment_status, latest.paid_at FROM orders s JOIN LATERAL (SELECT c.status AS payment_status, c.paid_at FROM payments c WHERE c.order_id = s.id ORDER BY c.paid_at DESC, c.id DESC LIMIT 1) latest ON TRUE), flagged AS (SELECT *, CASE WHEN LAG(paid_at) OVER (PARTITION BY payment_status ORDER BY paid_at, id) IS NULL OR paid_at > LAG(paid_at) OVER (PARTITION BY payment_status ORDER BY paid_at, id) + INTERVAL '90' DAY THEN 1 ELSE 0 END AS is_new_session FROM with_latest), islands AS (SELECT *, SUM(is_new_session) OVER (PARTITION BY payment_status ORDER BY paid_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS island_id FROM flagged), flagged_2 AS (SELECT *, CASE WHEN paid_at - LAG(paid_at) OVER (PARTITION BY payment_status ORDER BY paid_at, id) > INTERVAL 14 DAYS THEN 1 ELSE 0 END AS session_start_flag FROM islands), islands_orders AS (SELECT *, SUM(session_start_flag) OVER (PARTITION BY payment_status ORDER BY paid_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_id FROM flagged_2), metrics AS (SELECT *, SUM(island_id) OVER (PARTITION BY customer_id ORDER BY is_new_session, id ROWS BETWEEN 2 PRECEDING AND CURRENT ROW) last3_sum_island_id, COUNT(island_id) OVER (PARTITION BY customer_id ORDER BY is_new_session, id ROWS BETWEEN 2 PRECEDING AND CURRENT ROW) last3_count_island_id, AVG(island_id) OVER (PARTITION BY customer_id ORDER BY is_new_session, id ROWS BETWEEN 2 PRECEDING AND CURRENT ROW) last3_avg_island_id FROM islands_orders), kept AS (SELECT s.* FROM metrics s WHERE NOT EXISTS (SELECT 1 FROM order_items ch WHERE ch.order_id = s.id AND ch.product_id = 40)) SELECT id, store_id, order_date, paid_at, last3_sum_island_id, last3_count_island_id, COUNT(is_new_session) OVER (PARTITION BY payment_status, status ORDER BY last3_count_island_id, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) running_count_is_new_session, SUM(is_new_session) OVER (PARTITION BY payment_status, status ORDER BY last3_count_island_id, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) running_sum_is_new_session, MIN(is_new_session) OVER (PARTITION BY payment_status, status ORDER BY last3_count_island_id, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) running_min_is_new_session, NTILE(10) OVER (PARTITION BY store_id ORDER BY island_id, id) island_id_bucket FROM kept
